implementations.Rust:
// Rust implementation following semantic specification

use ndarray::Array1;

pub struct HRF {
    pub func: fn(&[f64]) -> Array1<f64>,
    pub name: String,
    pub nbasis: usize,
    pub span: f64,
}

impl HRF {
    pub fn evaluate(&self, t: &[f64]) -> Array1<f64> {
        (self.func)(t)
    }
}

/// Trapezoid quadrature nodes and weights over [0, width].
/// The weights sum to `width` exactly, for any `precision`.
pub fn block_offsets_weights(width: f64, precision: f64) -> (Vec<f64>, Vec<f64>) {
    let mut offsets: Vec<f64> = Vec::new();
    let mut x = 0.0;
    while x <= width + precision / 2.0 {
        offsets.push(x);
        x += precision;
    }
    if *offsets.last().unwrap() < width {
        offsets.push(width);
    }
    if offsets.len() == 1 {
        return (offsets, vec![1.0]);
    }

    let n = offsets.len();
    let deltas: Vec<f64> = (0..n - 1).map(|i| offsets[i + 1] - offsets[i]).collect();
    let mut weights = vec![0.0; n];
    weights[0] = deltas[0] / 2.0;
    weights[n - 1] = deltas[n - 2] / 2.0;
    for i in 1..n - 1 {
        weights[i] = (deltas[i - 1] + deltas[i]) / 2.0;
    }
    (offsets, weights)
}

pub fn evaluate_hrf_duration(
    hrf: &HRF,
    grid: &[f64],
    amplitude: f64,
    duration: f64,
    precision: f64,
    summate: bool,
    normalize: bool,
) -> Array1<f64> {
    // Branch on duration ALONE, never on duration relative to precision.
    let out = if duration <= 0.0 {
        // Point evaluation: an impulse of unit mass.
        amplitude * hrf.evaluate(grid)
    } else {
        let (offsets, weights) = block_offsets_weights(duration, precision);

        let n_time = grid.len();
        let mut result: Array1<f64> = Array1::zeros(n_time);

        // Weighted sum: the integral over the block.
        for (offset, weight) in offsets.iter().zip(weights.iter()) {
            let shifted: Vec<f64> = grid.iter().map(|&t| t - offset).collect();
            let values = amplitude * hrf.evaluate(&shifted);
            result = result + values * *weight;
        }

        if !summate {
            let weight_sum: f64 = weights.iter().sum();
            if weight_sum > 0.0 {
                result = result / weight_sum;
            }
        }

        result
    };

    // Apply normalization if requested
    if normalize {
        let peak_val = out.iter().map(|&x| x.abs()).fold(0.0, f64::max);
        if peak_val != 0.0 {
            out / peak_val
        } else {
            out
        }
    } else {
        out
    }
}

// Default parameters wrapper
pub fn evaluate_hrf_default(hrf: &HRF, grid: &[f64]) -> Array1<f64> {
    evaluate_hrf_duration(hrf, grid, 1.0, 0.0, 0.2, true, false)
}
